import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"履虎尾","description":"周易集解 - 履虎尾","frontmatter":{"title":"履虎尾","description":"周易集解 - 履虎尾"},"headers":[],"relativePath":"classics/jijie/010.md","filePath":"classics/jijie/010.md"}'),l={name:"classics/jijie/010.md"};function n(d,a,t,p,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="履虎尾" tabindex="-1">履虎尾 <a class="header-anchor" href="#履虎尾" aria-label="Permalink to “履虎尾”">​</a></h1><h2 id="履虎尾-1" tabindex="-1">履虎尾 <a class="header-anchor" href="#履虎尾-1" aria-label="Permalink to “履虎尾”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>履虎尾，不咥人。亨。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：物畜然後有禮，故受之以履。</p><p>崔憬曰：履，禮也。物畜不通，則君子先懿文德，然後以禮導之，故言物畜然後有禮也。</p><p>虞翻曰：謂變訟初為兌也。與謙旁通，以坤履乾，以柔履剛。謙坤為虎，艮為尾，乾為人，乾兌乘謙，震足蹈艮，故履虎尾。兌悅而應虎口，與上絕，故不咥人。剛當位，故通。俗儒皆以兌為虎，乾履兌，非也。兌剛滷，非柔也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：履，柔履剛也。說而應乎乾，是以履虎尾，不咥人。亨。剛中正，履帝位而不疚，光明也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：坤柔乾剛，謙坤籍乾，故柔履剛。</p><p>荀爽曰：謂三履二也。二五無應，故無元。以乾履兌，故有通。六三履二非和正，故雲利貞也。</p><p>虞翻曰：說，兌也。明兌不履乾，故言應也。</p><p>《九家易》曰：動來為兌而應上，故曰說而應乎乾也。以喻一國之君，應天子命以臨下。承上以巽，據下以悅，其正應天，故虎為之不咥人也。</p><p>《九家易》曰：虎尾，謂三也。三以說道履五之應，上順於天，故不咥人亨也。能巽說之道，順應於五，故雖踐虎，不見咥噬也。太平之代，虎不食人，亨謂於五也。</p><p>虞翻曰：剛中正，謂五。謙震為帝。五，帝位。坎為疾病，乾為大明。五履帝位，坎象不見。故「履帝位而不疚光明也」。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：上天下澤，履。君子以辯上下，定民志。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：君子，謂乾。辯，別也。乾天為上，兌澤為下。謙坤為民，坎為志。謙時坤在乾上，變而為履。故「辯上下，定民志也」。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，素履，往無咎。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：應在巽，為白，故素。履四失位，變往得正，故往無咎。初已得正，使四獨變，在外稱往。《象》曰：「獨行願也」。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：素履之往，獨行願也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：初九者，潛位。隱而未見，行而未成。素履者，謂布衣之士，未得居位，獨行禮義，不失其正，故無咎也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，履道坦坦，幽人貞吉。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：二失位。變成震，為道、為大塗，故履道坦坦。訟時二在坎獄中，故稱幽人，之正得位，震出兌悅，幽人喜笑，故貞吉也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：幽人貞吉，中不自亂也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：雖幽訟獄中，終辯得正，故不自亂。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，眇能視，跛能履，履虎尾，咥人，兇。武人為於大君。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：離目不正，兌為小，故眇而視。視上應也。訟坎為曳。變震時為足，足曳，故跛而履。俗儒多以兌刑為跛，兌折震足，為刑人見刑斷足者，非為跛也。</p><p>虞翻曰：艮為尾，在兌下，故履虎尾。位在虎口中，故咥人兇。既跛又眇，視步不能，為虎所齧，故咥人兇。《象》曰：「位不當也」。</p><p>虞翻曰：乾象在上，為武人。三失位，變而得正，成乾，故曰武人為於大君，志剛也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：眇能視，不足以有明也。跛能履，不足以與行也。咥人之兇，位不當也。武人為於大君，志剛也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：六三，兌也。互有離巽，離為目，巽為股。體俱非正，雖能視，眇目者也。雖能履，跛足者也。故曰「眇能視，不足以有明。跛能履，不足以與行」，是其義也。</p><p>案：六三為履卦之主。體悅應乾，下柔上剛，尊卑合道，是以「履虎尾，不咥人」通今於當爻以陰處陽，履非其位，互體離兌，水火相刑。故獨唯三被咥，兇矣。</p><p>案：以陰居陽，武人者也。三互體離，離為嚮明，為於大君，南面之象，與乾上應，故曰志剛。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，履虎尾，愬愬，終吉。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：體與下絕，四多懼，故愬愬。變體坎，得位，承五應初，故終吉。《象》曰：「志行也」。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：愬愬終吉，志行也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：愬愬，恐懼也。履乎兌主，履虎尾也。逼近至尊，故恐懼。以其恐懼，故終吉也。執乎樞密，故志行也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，夬履，貞厲。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：謂三上已變，體夬象，故夬履。四變五，在坎中也，為上所乘，故貞厲。《象》曰：「位正當也」。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：夬履貞厲，位正當也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>乾寶曰：夬，決也。居中履正，為履貴主。萬方所履，一決於前，恐決失正，恆懼危厲。故曰「夬履貞厲，位正當也」。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，視履考祥，其旋元吉。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：應在三，三先視上，故上亦視三。故曰「視履考祥」矣。考，稽。祥，善也。乾為積善，故「考祥」。三上易位，故「其旋元吉」。《象》曰：「大有慶也」。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：元吉在上，大有慶也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>盧氏曰：王者履禮於上，則萬方有慶於下。</p>',73)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
